	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/auth/2fa/enable", wrapper.TwoFactorEnable)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/auth/2fa/setup", wrapper.TwoFactorSetup)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/auth/login", wrapper.Login)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/auth/logout", wrapper.Logout)
